export function semRoteiroCurto2210(source, file) {
  const relative = typeof file === 'string' ? file.replace(/\\/g, '/') : file
  const hunks = HUNKS[relative]
  if (typeof source !== 'string' || !hunks || !source.includes(MARK)) return source
  // Validate against the ORIGINAL candidate before replacing anything. Moved JSX
  // must not create an anchor that another hunk could silently consume.
  const plans = hunks.map((hunk, index) => {
    const lf = offsets(source, hunk.after).map((at) => ({ at, length: hunk.after.length, replacement: hunk.before }))
    const afterCrLf = hunk.after.replace(/\n/g, '\r\n')
    const crlf = afterCrLf === hunk.after ? [] : offsets(source, afterCrLf).map((at) => ({ at, length: afterCrLf.length, replacement: hunk.before.replace(/\n/g, '\r\n') }))
    const matches = [...lf, ...crlf]
    if (matches.length !== 1) throw new Error(MARK + ': ' + relative + ' hunk ' + (index + 1) + ' ' + hunk.header + ': expected exactly 1 candidate match, found ' + matches.length)
    return matches[0]
  }).sort((left, right) => right.at - left.at)
  for (let index = 1; index < plans.length; index++) {
    if (plans[index].at + plans[index].length > plans[index - 1].at) throw new Error(MARK + ': overlapping candidate hunks in ' + relative)
  }
  let result = source
  for (const plan of plans) result = result.slice(0, plan.at) + plan.replacement + result.slice(plan.at + plan.length)
  return result
}
